+      color: var(--text);
+      background:
+        radial-gradient(circle at top, rgba(122, 162, 255, 0.16), transparent 32%),
+        linear-gradient(180deg, #0b1017, var(--bg));
+    }
+
+    main {
+      min-height: 100vh;
+      display: grid;
+      place-items: center;
+      padding: 32px 16px;
+    }
+
+    .card {
+      width: min(100%, 520px);
+      padding: 28px;
+      border: 1px solid var(--panel-border);
+      border-radius: 20px;
+      background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), rgba(255, 255, 255, 0.01)), var(--panel);
+      box-shadow: var(--shadow);
+    }
+
+    h1 {
+      margin: 0 0 10px;
+      font-size: clamp(1.5rem, 3vw, 2rem);
+      line-height: 1.15;
+      letter-spacing: -0.02em;
+    }
+
+    .lede {
+      margin: 0 0 24px;
+      color: var(--muted);
+    }
+
+    form {
+      display: grid;
+      gap: 18px;
+    }
+
+    .form-field {
+      display: grid;
+      grid-template-columns: auto 1fr;
+      gap: 12px 14px;
+      align-items: start;
+      padding: 18px;
+      border: 1px solid var(--panel-border);
+      border-radius: 16px;
+      background: rgba(255, 255, 255, 0.02);
+    }
+
+    .form-field input[type="checkbox"] {
+      width: 1.15rem;
+      height: 1.15rem;
+      margin: 0.18rem 0 0;
+      accent-color: var(--accent);
+    }
+
+    .form-field label {
+      display: inline-block;
+      font-weight: 600;
+      color: var(--text);
+      cursor: pointer;
+    }
+
+    .required {
+      color: var(--accent-strong);
+    }
+
+    .help-text {
+      grid-column: 2;
+      margin: 0;
+      color: var(--muted);
+      font-size: 0.95rem;
+    }
+
+    .actions {
+      display: flex;
+      flex-wrap: wrap;
+      gap: 12px;
+      align-items: center;
+    }
+
+    button {
+      appearance: none;
+      border: 1px solid transparent;
+      border-radius: 999px;
+      padding: 0.8rem 1.2rem;
+      font: inherit;
+      font-weight: 700;
+      color: #06101f;
+      background: linear-gradient(180deg, #9ab7ff, var(--accent));
+      box-shadow: 0 10px 24px rgba(122, 162, 255, 0.24);
+      cursor: pointer;
+    }
+
+    button:hover {
+      filter: brightness(1.05);
+    }
+
+    button:focus-visible,
+    input:focus-visible,
+    label:focus-visible {
+      outline: 3px solid var(--focus);
+      outline-offset: 3px;
+    }
+
+    .status {
+      margin: 0;
+      min-height: 1.5em;
+      color: #cfe1ff;
+    }
+
+    @media (max-width: 420px) {
+      .card {
+        padding: 20px;
+      }
+
+      .form-field {
+        padding: 16px;
+      }
+    }
+
+    @media (forced-colors: active) {
+      :root {
+        --panel: Canvas;
+        --panel-border: CanvasText;
+        --text: CanvasText;
+        --muted: CanvasText;
+        --accent: LinkText;
+        --accent-strong: LinkText;
+        --focus: Highlight;
+      }
+
+      .card,
+      .form-field,
+      button {
+        forced-color-adjust: auto;
+      }
+
+      button {
+        color: ButtonText;
+        background: ButtonFace;
+        border-color: ButtonText;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <section class="card" aria-labelledby="page-title">
+      <h1 id="page-title">Terms of Use consent</h1>
+      <p class="lede">Please review the terms and confirm your agreement to continue.</p>
+
+      <form id="consent-form" novalidate>
+        <div class="form-field">
+          <input
+            id="terms"
+            name="terms"
+            type="checkbox"
+            required
+            aria-describedby="terms-help"
+          >
+          <div>
+            <label for="terms">
+              I agree to the Terms of Use <span class="required" aria-hidden="true">*</span>
+            </label>
+            <p id="terms-help" class="help-text">Required to continue.</p>
+          </div>
+        </div>
+
+        <div class="actions">
+          <button type="submit">Continue</button>
+          <p id="consent-status" class="status" role="status" aria-live="polite"></p>
+        </div>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById('consent-form');
+    const checkbox = document.getElementById('terms');
+    const status = document.getElementById('consent-status');
+
+    form.addEventListener('submit', (event) => {
+      if (!checkbox.checked) {
+        return;
+      }
+
+      event.preventDefault();
+      status.textContent = 'Thanks — your consent was recorded.';
+      form.reset();
+      checkbox.focus();
+    });
+
+    checkbox.addEventListener('change', () => {
+      status.textContent = '';
+    });
+  </script>
+</body>
+</html>
*** End Patch
