       display: grid;
       gap: 18px;
     }

     .form-field {
       display: grid;
       grid-template-columns: auto 1fr;
       gap: 12px 14px;
       align-items: start;
       padding: 18px;
       border: 1px solid var(--panel-border);
       border-radius: 16px;
       background: rgba(255, 255, 255, 0.02);
     }

     .form-field input[type="checkbox"] {
       width: 1.15rem;
       height: 1.15rem;
       margin: 0.18rem 0 0;
       accent-color: var(--accent);
     }

