       display: inline-block;
       font-weight: 600;
       color: var(--text);
       cursor: pointer;
     }

     .required {
       color: var(--accent-strong);
     }

     .help-text {
       grid-column: 2;
       margin: 0;
       color: var(--muted);
       font-size: 0.95rem;
     }

     .actions {
       display: flex;
       flex-wrap: wrap;
       gap: 12px;
       align-items: center;
     }

     button {
       appearance: none;
       border: 1px solid transparent;
       border-radius: 999px;
       padding: 0.8rem 1.2rem;
       font: inherit;
       font-weight: 700;
