       background: linear-gradient(180deg, #9ab7ff, var(--accent));
       box-shadow: 0 10px 24px rgba(122, 162, 255, 0.24);
       cursor: pointer;
     }

     button:hover {
       filter: brightness(1.05);
     }

     button:focus-visible,
     input:focus-visible,
     label:focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 3px;
     }

     .status {
       margin: 0;
       min-height: 1.5em;
       color: #cfe1ff;
     }

