     @media (forced-colors: active) {
       :root {
         --panel: Canvas;
         --panel-border: CanvasText;
         --text: CanvasText;
         --muted: CanvasText;
         --accent: LinkText;
         --accent-strong: LinkText;
         --focus: Highlight;
       }

       .card,
       .form-field,
       button {
         forced-color-adjust: auto;
       }

       button {
         color: ButtonText;
         background: ButtonFace;
         border-color: ButtonText;
       }
     }
   </style>
 </head>
 <body>
   <main>
     <section class="card" aria-labelledby="page-title">
       <h1 id="page-title">Terms of Use consent</h1>
       <p class="lede">Please review the terms and confirm your agreement to continue.</p>

       <form id="consent-form">
         <div class="form-field">
           <input
             id="terms"
             name="terms"
             type="checkbox"
             required
             aria-describedby="terms-help"
           >
           <div>
             <label for="terms">
               I agree to the Terms of Use <span class="required" aria-hidden="true">*</span>
             </label>
             <p id="terms-help" class="help-text">Required to continue.</p>
           </div>
         </div>

         <div class="actions">
           <button type="submit">Continue</button>
           <p id="consent-status" class="status" role="status" aria-live="polite"></p>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('consent-form');
     const checkbox = document.getElementById('terms');
     const status = document.getElementById('consent-status');

     form.addEventListener('submit', (event) => {
       if (!checkbox.checked) {
         return;
       }

       event.preventDefault();
       status.textContent = 'Thanks — your consent was recorded.';
       form.reset();
       checkbox.focus();
     });

     checkbox.addEventListener('change', () => {
       status.textContent = '';
     });
   </script>
 </body>
 </html>

