      event.preventDefault();
      checkbox.setAttribute('aria-invalid', 'false');
      document.getElementById('terms-error').hidden = true;
      status.textContent = 'Thanks — your consent was recorded.';
      form.reset();
      checkbox.focus();
    });

    checkbox.addEventListener('input', () => {
      if (checkbox.checked) {
        checkbox.setAttribute('aria-invalid', 'false');
        document.getElementById('terms-error').hidden = true;
      }
      status.textContent = '';
    });
  </script>
</body>
